function artSVG(parts){return parts.map(q=>q.ellipse?`<ellipse cx="${q.ellipse[0]}" cy="${q.ellipse[1]}" rx="${q.ellipse[2]}" ry="${q.ellipse[3]}" fill="${q.fill}" opacity="${q.alpha??1}"/>`:`<path d="M${q.v.map(v=>v.join(' ')).join('L')}${q.c?'Z':''}" fill="${q.fill||'none'}" stroke="${q.stroke||'none'}" stroke-width="${q.width||1}" stroke-linejoin="round" stroke-linecap="round" opacity="${q.alpha??1}"/>`).join('');}
function registerArt(kind,w,h,parts){vectorArt[kind]={w,h,parts};extraAssets[kind]=svgAsset(artSVG(parts),w,h);}
// Framed modules, individual cell lines and rear supports share SVG/Lottie geometry.
const panel=[],panelPoint=(u,v)=>[10+198*u+82*v,134+102*u-110*v];
